def file_category(ext: str, is_dir: bool) -> str:
    if is_dir:
        return "folder"
    for cat, exts in CATEGORIES.items():
        if ext in exts:
            return cat
    return "file"


def fmt_size(size: int) -> str:
    if size is None:
        return ""
    units = ["B", "KB", "MB", "GB", "TB"]
    i = 0
    n = float(size)
    while n >= 1024 and i < len(units) - 1:
        n /= 1024
        i += 1
    return f"{n:.0f} {units[i]}" if i == 0 else f"{n:.1f} {units[i]}"


def is_excluded(name: str) -> bool:
    """A name is excluded if it's in EXCLUDE_NAMES or starts with an excluded prefix."""
    if name in EXCLUDE_NAMES:
        return True
    for p in EXCLUDE_PREFIXES:
        if name.startswith(p):
            return True
    # Case-insensitive match for sidebar-related markdown (any case).
    # readme.md is hidden by convention; notes.md is hidden because it's
    # rendered into the sidebar instead.
    if name.lower() in ("readme.md", "notes.md"):
        return True
    return False


# ---------- Markdown renderer (mirrors the PHP version) ----------
def render_markdown(md: str, rel_base: str = "") -> str:
    md = md.replace("\r\n", "\n").replace("\r", "\n")

    # Extract fenced code blocks first
    code_blocks = []

    def stash_code(m):
        code_blocks.append(f"<pre><code>{html.escape(m.group(1))}</code></pre>")
        return f"\x00CB{len(code_blocks) - 1}\x00"

    md = re.sub(r"```[a-zA-Z0-9_-]*\n(.*?)\n```", stash_code, md, flags=re.DOTALL)

    out = []
    para = []
    list_type = None  # 'ul' | 'ol' | None

    def flush_para():
        if para:
            out.append(f"<p>{process_inline(' '.join(para), rel_base)}</p>")
            para.clear()

    def close_list():
        nonlocal list_type
        if list_type:
            out.append(f"</{list_type}>")
            list_type = None

    for line in md.split("\n"):
        t = line.strip()

        m = re.match(r"^\x00CB(\d+)\x00$", t)
        if m:
            flush_para(); close_list()
            out.append(code_blocks[int(m.group(1))])
            continue

        if t == "":
            flush_para(); close_list()
            continue

        m = re.match(r"^(#{1,6})\s+(.+?)\s*#*$", t)
        if m:
            flush_para(); close_list()
            lvl = len(m.group(1))
            out.append(f"<h{lvl}>{process_inline(m.group(2), rel_base)}</h{lvl}>")
            continue

        if re.match(r"^(-{3,}|\*{3,}|_{3,})$", t):
            flush_para(); close_list()
            out.append("<hr>")
            continue

        m = re.match(r"^>\s?(.*)$", t)
        if m:
            flush_para(); close_list()
            out.append(f"<blockquote>{process_inline(m.group(1), rel_base)}</blockquote>")
            continue

        m = re.match(r"^[-*+]\s+(.+)$", t)
        if m:
            flush_para()
            if list_type != "ul":
                close_list()
                out.append("<ul>")
                list_type = "ul"
            out.append(f"<li>{process_inline(m.group(1), rel_base)}</li>")
            continue

        m = re.match(r"^\d+\.\s+(.+)$", t)
        if m:
            flush_para()
            if list_type != "ol":
                close_list()
                out.append("<ol>")
                list_type = "ol"
            out.append(f"<li>{process_inline(m.group(1), rel_base)}</li>")
            continue

        close_list()
        para.append(t)

    flush_para(); close_list()
    return "".join(out)


def process_inline(text: str, rel_base: str) -> str:
    text = html.escape(text, quote=False)

    def resolve_url(url: str) -> str:
        check = url.strip().lower()
        if re.match(r"^(javascript|vbscript|data):", check):
            return "#"
        if re.match(r"^(https?://|mailto:|/|#)", url, flags=re.I):
            return url
        return url if rel_base == "" else f"{rel_base}/{url}"

    text = re.sub(r"`([^`]+)`", lambda m: f"<code>{m.group(1)}</code>", text)
    text = re.sub(
        r"!\[([^\]]*)\]\(([^)\s]+)\)",
        lambda m: f'<img src="{resolve_url(m.group(2))}" alt="{m.group(1)}">',
        text,
    )
    text = re.sub(
        r"\[([^\]]+)\]\(([^)\s]+)\)",
        lambda m: f'<a href="{resolve_url(m.group(2))}" target="_blank" rel="noopener">{m.group(1)}</a>',
        text,
    )
    text = re.sub(r"\*\*([^*\n]+)\*\*", r"<strong>\1</strong>", text)
    text = re.sub(r"(?<![A-Za-z0-9_])__([^_\n]+)__(?![A-Za-z0-9_])", r"<strong>\1</strong>", text)
    text = re.sub(r"\*([^*\n]+)\*", r"<em>\1</em>", text)
    text = re.sub(r"(?<![A-Za-z0-9_])_([^_\n]+)_(?![A-Za-z0-9_])", r"<em>\1</em>", text)
    return text


