def render_icon(cat: str) -> str:
    body = ICON_PATHS.get(cat, ICON_PATHS["file"])
    return f'<svg class="icon icon-{cat}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">{body}</svg>'


# ---------- Main build ----------
def collect_entries(dir_path: Path):
    """Return entries in this directory (excluding hidden/excluded/readme)."""
    entries = []
    for child in sorted(dir_path.iterdir(), key=lambda p: (not p.is_dir(), p.name.lower())):
        name = child.name
        if is_excluded(name):
            continue
        is_dir = child.is_dir()
        try:
            stat = child.stat()
            mtime = stat.st_mtime
            size = None if is_dir else stat.st_size
        except OSError:
            mtime, size = 0, None
        ext = "" if is_dir else child.suffix.lstrip(".").lower()
        entries.append({
            "name": name,
            "is_dir": is_dir,
            "size": size,
            "mtime": mtime,
            "ext": ext,
        })
    return entries


def build_crumbs(rel: str, depth_to_root: str) -> str:
    """rel: posix path relative to root, '' for root.
    depth_to_root: '' for root, '../' * depth for subdirs."""
    parts = [("Home", depth_to_root or "./")]
    if rel:
        accum_segments = []
        for seg in rel.split("/"):
            accum_segments.append(seg)
            # build href: from current dir, go up depth, then down into accum_segments
            up = depth_to_root or ""
            href = up + "/".join(accum_segments) + "/"
            parts.append((seg, href))
    out = []
    for i, (label, href) in enumerate(parts):
        if i > 0:
            out.append('<span class="sep">/</span>')
        out.append(f'<a href="{html.escape(href)}">{html.escape(label)}</a>')
    return "".join(out)


def build_index_for_dir(repo_root: Path, dir_path: Path):
    """Generate index.html for this directory. Returns True if written."""
    rel = dir_path.relative_to(repo_root).as_posix()
    if rel == ".":
        rel = ""

    entries = collect_entries(dir_path)
    depth = 0 if rel == "" else rel.count("/") + 1
    depth_to_root = "../" * depth if depth else ""

    # Detect notes.md (case-insensitive) — rendered into the sidebar.
    # Variable kept named readme_html for template-placeholder compatibility.
    readme_html = ""
    for entry_name in os.listdir(dir_path):
        if entry_name.lower() == "notes.md" and (dir_path / entry_name).is_file():
            try:
                content = (dir_path / entry_name).read_text(encoding="utf-8", errors="ignore")
                if content.strip():
                    rendered = render_markdown(content, "")  # links resolve relative to this dir
                    readme_html = f'<li class="readme-row"><div class="readme">{rendered}</div></li>'
            except Exception:
                pass
            break

    # Detect default file (auto-load in iframe).
    # DEFAULT_FILES intentionally bypasses is_excluded — PROTOTYPE_FILENAME is
    # in EXCLUDE_NAMES (to hide it from listings/search) but should still load.
    initial_view_name = ""
    for cand in DEFAULT_FILES:
        cand_path = dir_path / cand
        cand_ext = cand.rsplit(".", 1)[-1].lower() if "." in cand else ""
        if cand_path.is_file() and cand_ext in IFRAME_EXTS:
            initial_view_name = cand
            break

    # Build entry rows
    rows = []
    for e in entries:
        cat = file_category(e["ext"], e["is_dir"])
        # href: folders go to subdir/; files are direct file links
        if e["is_dir"]:
            href = f'{html.escape(e["name"])}/'
        else:
            href = html.escape(e["name"])
        iframable = (not e["is_dir"]) and e["ext"] in IFRAME_EXTS
        is_active = (initial_view_name and e["name"] == initial_view_name)

        date_str = datetime.fromtimestamp(e["mtime"]).strftime(DATE_FORMAT) if e["mtime"] else ""
        if e["is_dir"]:
            meta = date_str
        else:
            size_part = fmt_size(e["size"])
            meta = f"{size_part} · {date_str}".strip(" ·") if date_str else size_part

        attrs = [
            f'href="{href}"',
            f'data-name="{html.escape(e["name"], quote=True)}"',
            f'data-size="{e["size"] or 0}"',
            f'data-mtime="{int(e["mtime"])}"',
            f'data-cat="{cat}"',
        ]
        if iframable:
            # absolute href from current page (just the filename for files in this dir)
            attrs.append('data-iframe="1"')
            attrs.append(f'data-abs-href="{href}"')

        active_cls = " active" if is_active else ""
        rows.append(
            f'<li><a class="row{active_cls}" {" ".join(attrs)}>'
            f'{render_icon(cat)}'
            f'<div class="info"><div class="name">{html.escape(e["name"])}</div>'
            f'<div class="meta">{html.escape(meta)}</div></div></a></li>'
        )

    # Parent row (only if we're in a subfolder)
    parent_row = ""
    if rel:
        parent_row = (
            '<li><a class="row parent" href="../">'
            '<svg class="icon icon-up" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="m12 19-7-7 7-7"/><path d="M19 12H5"/></svg>'
            '<div class="info"><div class="name">Back</div></div>'
            '</a></li>'
        )

    empty_note = '<li class="empty-list">This folder is empty.</li>' if (not entries and not rel) else ""

    # Initial state
    is_html_view = initial_view_name and initial_view_name.lower().endswith((".html", ".htm"))
    initial_lock = "" if is_html_view else "locked-open"
    viewer_active = "true" if initial_view_name else "false"
    frame_src = html.escape(initial_view_name) if initial_view_name else ""

    display_path = "/" + rel
    crumbs_html = build_crumbs(rel, depth_to_root)
    search_index_path = depth_to_root + "_search-index.json"
    site_base = depth_to_root or "./"

    output = HTML_TEMPLATE
    replacements = {
        "__TITLE__": html.escape(TITLE),
        "__DISPLAY_PATH__": html.escape(display_path),
        "__INITIAL_LOCK__": initial_lock,
        "__CRUMBS__": crumbs_html,
        "__README_BLOCK__": readme_html,
        "__PARENT_ROW__": parent_row,
        "__ENTRY_ROWS__": "\n".join(rows),
        "__EMPTY_NOTE__": empty_note,
        "__VIEWER_ACTIVE__": viewer_active,
        "__FRAME_SRC__": frame_src,
        "__SEARCH_INDEX_PATH__": search_index_path,
        "__SITE_BASE__": site_base,
    }
    for k, v in replacements.items():
        output = output.replace(k, v)

    # Marker so we know we wrote this. Placed at the top so stale-file
    # detection can find it cheaply on the next build.
    output = output.replace(
        "<!DOCTYPE html>", f"<!DOCTYPE html>\n{BUILD_MARKER}", 1
    )

    out_path = dir_path / "index.html"
    out_path.write_text(output, encoding="utf-8")
    return True


def build_search_index(repo_root: Path) -> int:
    """Walk the entire tree and emit _search-index.json. Returns the entry count."""
    items = []
    for dirpath, dirnames, filenames in os.walk(repo_root):
        # Filter dirs in place to skip excluded ones (also prunes traversal)
        dirnames[:] = [d for d in dirnames if not is_excluded(d)]
        d = Path(dirpath)
        rel_dir = d.relative_to(repo_root).as_posix()
        if rel_dir == ".":
            rel_dir = ""

        # Add directories
        for name in dirnames:
            full = (d / name)
            rel = (rel_dir + "/" + name) if rel_dir else name
            items.append({
                "name": name,
                "path": rel,
                "parent": rel_dir,
                "isDir": True,
                "iframable": False,
                "cat": "folder",
            })

        # Add files
        for name in filenames:
            if is_excluded(name):
                continue
            ext = name.rsplit(".", 1)[-1].lower() if "." in name else ""
            rel = (rel_dir + "/" + name) if rel_dir else name
            items.append({
                "name": name,
                "path": rel,
                "parent": rel_dir,
                "isDir": False,
                "iframable": ext in IFRAME_EXTS,
                "cat": file_category(ext, False),
            })

    out_path = repo_root / "_search-index.json"
    out_path.write_text(json.dumps(items, separators=(",", ":")), encoding="utf-8")
    return len(items)


def copy_source_to_output(src_root: Path, out_root: Path) -> list[str]:
    """Copy src_root to out_root, skipping excluded names. Returns a list of
    relative paths to stale generated files (committed `index.html` files
    containing BUILD_MARKER) that were skipped — for printing as warnings.

    A previous in-place build may have committed generated index.html files
    into the repo; those should NOT be treated as real prototypes. We detect
    them by content marker and exclude them from the copy.
    """
    if out_root.exists():
        shutil.rmtree(out_root)

    stale: list[str] = []

    def ignore(dir_str: str, names: list[str]) -> set[str]:
        skip: set[str] = set()
        d = Path(dir_str)
        for name in names:
            # Dotfiles (.git, .DS_Store, .gitignore, .nojekyll, ...)
            if any(name.startswith(p) for p in EXCLUDE_PREFIXES):
                skip.add(name)
                continue
            # Build artifacts and config we never copy into the output
            if name in COPY_SKIP_NAMES:
                skip.add(name)
                continue
            # Detect stale generated index.html in source: copied by previous
            # in-place builds; do not treat as a real prototype.
            # Read window is 64KB — older builds placed the marker near
            # </head>, which can sit ~10KB into the file due to embedded CSS.
            if name == "index.html":
                p = d / name
                try:
                    if p.is_file():
                        head = p.read_text(encoding="utf-8", errors="ignore")[:65536]
                        if BUILD_MARKER in head:
                            try:
                                rel = p.relative_to(src_root).as_posix()
                            except ValueError:
                                rel = str(p)
                            stale.append(rel)
                            skip.add(name)
                except OSError:
                    pass
        return skip

    shutil.copytree(src_root, out_root, ignore=ignore, dirs_exist_ok=False)
    return stale


def find_user_landings(out_root: Path) -> list[Path]:
    """Walk out_root and return absolute paths to every directory containing a
    user-provided `index.html` (a bare landing page). Stale generated
    listings were already filtered out during the copy, so any `index.html`
    present here is a real user file. Also enforces the rule that a folder
    cannot contain both `index.html` and LANDING_FILENAME — those represent
    contradictory intents (bare vs. wrapped) and indicate an authoring error.
    """
    bare_dirs: list[Path] = []
    for dirpath, dirnames, filenames in os.walk(out_root):
        if "index.html" not in filenames:
            continue
        d = Path(dirpath)
        if LANDING_FILENAME in filenames:
            rel = d.relative_to(out_root).as_posix() or "/"
            print(
                f"Error: {rel} contains both index.html (bare landing) and "
                f"{LANDING_FILENAME} (wrapped landing). These are "
                f"contradictory — keep one and delete the other.",
                file=sys.stderr,
            )
            sys.exit(1)
        bare_dirs.append(d)
    return bare_dirs


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("--root", default=".", help="Source root (default: current dir)")
    args = parser.parse_args()

    src_root = Path(args.root).resolve()
    if not src_root.is_dir():
        print(f"Error: {src_root} is not a directory", file=sys.stderr)
        sys.exit(1)

    out_root = src_root / OUTPUT_DIR

    print(f"Source: {src_root}")
    print(f"Output: {out_root}")
    print()

    # Pass 1: copy source -> _site, skipping excluded + stale generated files
    stale = copy_source_to_output(src_root, out_root)
    if stale:
        print("Warning: skipped stale generated files in source (left over from")
        print("a previous in-place build). Please delete these from the repo:")
        for p in stale:
            print(f"  - {p}")
        print()

    # Pass 2: identify folders the user wants served as bare landing pages
    # (a user index.html lives there; no sidebar wraps it). The build will
    # not overwrite these.
    bare_dirs = find_user_landings(out_root)
    bare_set = {d.resolve() for d in bare_dirs}

    # Pass 3: generate index.html listings for every directory EXCEPT those
    # the user has claimed for a bare landing.
    written = 0
    skipped_bare = 0
    for dirpath, dirnames, _ in os.walk(out_root):
        dirnames[:] = [d for d in dirnames if not is_excluded(d)]
        d = Path(dirpath)
        rel = d.relative_to(out_root).as_posix()
        if rel == ".":
            rel = ""
        if d.resolve() in bare_set:
            print(f"  {rel or '/'}  (bare landing — skipping listing generation)")
            skipped_bare += 1
            continue
        print(f"  {rel or '/'}")
        if build_index_for_dir(out_root, d):
            written += 1

    # Generate search index at the root of _site
    count = build_search_index(out_root)
    print()
    print(f"Wrote {written} index.html listings")
    if skipped_bare:
        print(
            f"Left {skipped_bare} user index.html file(s) in place as bare "
            f"landing page(s). To wrap one in the sidebar instead, rename it "
            f"to {LANDING_FILENAME}."
        )
    print(f"Search index: {count} entries -> {OUTPUT_DIR}/_search-index.json")

    # .nojekyll so GH Pages doesn't filter _search-index.json
    nojekyll = out_root / ".nojekyll"
    if not nojekyll.exists():
        nojekyll.write_text("", encoding="utf-8")
        print(f"Created {OUTPUT_DIR}/.nojekyll (prevents Jekyll filtering)")


if __name__ == "__main__":
    main()
